workspace.calc.dart:
String pad(String s, int n) => s.padLeft(n, '.');

String truncate(String s, int n) => n < s.length ? '${s.substring(0, n)}...' : s;

num sum(List<num> xs) => xs.fold(0, (a, b) => a + b);

num avg(List<num> xs) => xs.isEmpty ? 0 : sum(xs) / xs.length;

workspace.verify.sh:
#!/bin/sh
out1=$(dart main.dart | tr '\n' ' ' | sed -e 's/[[:space:]]*$//')
out2=$(dart stats.dart | tr '\n' ' ' | sed -e 's/[[:space:]]*$//')
ok=1
[ ! -f calc.dart ] || { echo 'FAIL calc.dart still present'; ok=0; }
[ "$out1" = '...go grad...' ] || { echo "FAIL main: $out1"; ok=0; }
[ "$out2" = '6 3.0' ] || { echo "FAIL stats: $out2"; ok=0; }
[ "$ok" = 1 ] && echo 'STRUCTURE-OK'
